def sum_first_n_fibonacci(n):
    if n <= 0:
        return 0
    fibs = [0] * n
    if n >= 2:
        fibs[1] = 1
    for i in range(2, n):
        fibs[i] = fibs[i - 1] + fibs[i - 2]
    return sum(fibs)

