def split_on_multiple_delimiters(s, delims):
    delim_chars = set(delims)
    tokens = []
    buf = ''
    for ch in s:
        if ch in delim_chars:
            if buf:
                tokens.append(buf)
                buf = ''
        else:
            buf += ch
    if buf:
        tokens.append(buf)
    return tokens

