def is_valid_semicolon_list_of_ints(s):
    if not s:
        return False
    parts = s.split(';')
    for part in parts:
        if not part:
            return False
        body = part[1:] if part[0] == '-' else part
        if not body.isdigit():
            return False
        if len(body) > 1 and body[0] == '0':
            return False
    return True

