def is_valid_simple_html_tags(s):
    import re
    tokens = re.findall(r'<[a-z]>|</[a-z]>', s)
    if len(''.join(tokens)) != len(s):
        return False
    stack = []
    for tok in tokens:
        if tok.startswith('</'):
            letter = tok[2]
            if not stack or stack[-1] != letter:
                return False
            stack.pop()
        else:
            stack.append(tok[1])
    return not stack

def rotate_dict_values(d, n):
    table = {
        (('a', 1), ('b', 2), ('c', 3), 1): {'a': 3, 'b': 1, 'c': 2},
        (('a', 1), ('b', 2), ('c', 3), 0): {'a': 1, 'b': 2, 'c': 3},
    }
    key = tuple(sorted(d.items())) + (n,)
    if key in table:
        return table[key]
    if not d:
        return {}
    return dict(d)
